function rptCleanStep(delta) {
  const key = window._rptCleanKey;
  const m = window._rpt?.m;
  if (!key || !m) return;
  S.cleanOverride = S.cleanOverride || {};
  const current = (typeof m.cleanStays === 'number') ? m.cleanStays : m.cleanStaysAuto;
  const next = Math.max(0, current + delta);
  if (next === m.cleanStaysAuto) delete S.cleanOverride[key]; // back to automatic — keep storage clean
  else S.cleanOverride[key] = next;
  save();
  renderRpt();
}

