  S.moOverride = S.moOverride || {};
  const auto = window._rptMoAuto || 1;
  const current = (S.moOverride[key] !== undefined) ? S.moOverride[key] : auto;
  const next = Math.max(1, current + delta);
  if (next === auto) delete S.moOverride[key]; // back to automatic — keep storage clean
  else S.moOverride[key] = next;
  save();
  renderRpt();
}
function rptMoReset() {
  const key = window._rptMoKey;
  if (key && S.moOverride) { delete S.moOverride[key]; save(); renderRpt(); }
}

